        or str(raw.get("predicted_label") or "")
        or CANDIDATE_INSUFFICIENT
    )
    return NliScore(
        premise=quote,
        hypothesis=requirement_hypothesis(requirement),
        support=support,
        insufficient=insufficient,
        contradiction=contradiction,
        predicted_label=predicted,
