function applyCandidateOverrideLocally(
  current: PolicyEvaluation,
  updated: EvidenceCandidate,
  status: CandidateStatus,
): PolicyEvaluation {
  const patchCandidate = (candidate: EvidenceCandidate): EvidenceCandidate =>
    candidate.id === updated.id
      ? {
          ...candidate,
          ...updated,
          clinician_override: status,
          display_status: status,
          verification_status: status,
        }
      : candidate;

  const requirements = current.requirements.map((item) => {
    if (item.requirement_id !== updated.requirement_id) return item;
    const all = [
      ...(item.support_candidates ?? item.supporting_candidates ?? []),
      ...(item.insufficient_candidates ?? item.review_candidates ?? []),
    ].map(patchCandidate);
    // Keep the overridden citation visible; bucket by clinician status.
    const support = all.filter(
      (c) =>
        (c.display_status || c.verification_status) === "support" ||
        c.id === updated.id && status === "support",
    );
    const insufficient = all.filter((c) => {
      const s = c.id === updated.id ? status : c.display_status || c.verification_status;
      return s === "insufficient";
    });
    const contradiction = all.filter((c) => {
      const s = c.id === updated.id ? status : c.display_status || c.verification_status;
      return s === "contradiction";
    });
    // Citations list still shows support + insufficient only (existing UI).
    const visibleSupport = [
      ...support,
      ...contradiction.filter((c) => c.id === updated.id && status === "contradiction"),
    ];
    // Prefer keeping all citations that were already shown, plus updated.
    const citations = all;
    const nextStatus: CandidateStatus =
      support.length > 0
        ? "support"
        : insufficient.length > 0
          ? "insufficient"
          : "contradiction";
    const next: RequirementEvaluation = {
      ...item,
      status: nextStatus,
      explanation:
        nextStatus === "support"
          ? ""
          : nextStatus === "insufficient"
            ? item.explanation
            : item.explanation,
      support_candidate_ids: support.map((c) => c.id),
      insufficient_candidate_ids: insufficient.map((c) => c.id),
      contradiction_candidate_ids: contradiction.map((c) => c.id),
      support_candidates: citations.filter(
        (c) => (c.id === updated.id ? status : c.display_status || c.verification_status) === "support",
      ),
      insufficient_candidates: citations.filter(
        (c) =>
          (c.id === updated.id ? status : c.display_status || c.verification_status) ===
          "insufficient",
      ),
      supporting_candidates: undefined,
      review_candidates: undefined,
    };
    // Silence unused for lint in case of tree-shake; keep logic readable.
    void visibleSupport;
    return next;
  });

  const statuses = requirements.map((r) => r.status);
  const overall =
    current.logic.toUpperCase() === "OR"
      ? statuses.includes("support")
        ? "support"
        : statuses.includes("insufficient")
          ? "insufficient"
          : "contradiction"
      : statuses.every((s) => s === "support")
        ? "support"
        : statuses.includes("insufficient")
          ? "insufficient"
          : "contradiction";

  return { ...current, overall_status: overall, requirements };
}

