"use client";

import type {
  DocumentSummary,
  EvidenceCandidate,
  PolicyEvaluation,
  RequirementEvaluation,
} from "@/lib/types";

type EvidencePacketPanelProps = {
  evaluation: PolicyEvaluation | null;
  documents: DocumentSummary[];
  selectedDocumentIds: string[];
  onToggleDocument: (documentId: string, selected: boolean) => void;
  onOpenDocument: (documentId: string) => void;
  onExport: () => void;
};

function typeLabel(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return "Uploaded";
  return trimmed.replaceAll("_", " ");
}

function statusStyles(status: string) {
  switch (status) {
    case "insufficient":
    case "NEEDS_REVIEW":
      return "border-[#c48a2e]/45 bg-[#fff6e8] text-[#8a6230]";
    case "contradiction":
    case "NOT_ESTABLISHED":
      return "border-[#b45656]/40 bg-[#fbeaea] text-[#8f3d3d]";
    case "support":
    case "SUPPORTED":
      return "border-[#1b7a6d]/50 bg-[#e7f6f2] text-[#0f5a51]";
    default:
      return "border-line bg-mist/60 text-ink-soft";
  }
}

function citationIsSupport(candidate: EvidenceCandidate) {
  const status =
    candidate.display_status ||
    candidate.clinician_override ||
    candidate.model_status ||
    candidate.verification_status;
  return status === "support" || status === "accepted" || status === "SUPPORTED";
}

function supportCandidatesFor(item: RequirementEvaluation) {
  const all = [
    ...(item.support_candidates ?? item.supporting_candidates ?? []),
    ...(item.insufficient_candidates ?? item.review_candidates ?? []),
    ...(item.contradiction_candidates ?? []),
  ];
  const seen = new Set<string>();
  const out: EvidenceCandidate[] = [];
  for (const candidate of all) {
    if (!citationIsSupport(candidate)) continue;
    if (seen.has(candidate.document_id)) continue;
    seen.add(candidate.document_id);
    out.push(candidate);
  }
  return out;
}

function missingRequirements(evaluation: PolicyEvaluation) {
  return evaluation.requirements.filter(
    (item) => supportCandidatesFor(item).length === 0,
  );
}

export function EvidencePacketPanel({
  evaluation,
  documents,
  selectedDocumentIds,
  onToggleDocument,
  onOpenDocument,
  onExport,
}: EvidencePacketPanelProps) {
  const docById = new Map(documents.map((doc) => [doc.id, doc]));
  const selected = new Set(selectedDocumentIds);

  if (!evaluation) {
    return (
      <section className="border-t border-line/70 pt-5">
        <h2 className="font-display text-2xl text-ink">Evidence packet</h2>
        <p className="mt-2 text-sm text-muted">
          Evaluate insurance requirements first, then choose which supporting
          documents to include in the packet.
        </p>
      </section>
    );
  }

  const missing = missingRequirements(evaluation);
  const selectedCount = selectedDocumentIds.length;

  return (
    <section className="space-y-10">
      <div>
        <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
          <div>
            <h2 className="font-display text-2xl text-ink">Evidence packet</h2>
            <p className="mt-1 max-w-2xl text-sm leading-6 text-ink-soft">
              Choose among documents marked support for each requirement.
              Changing status on the requirements tab adds or removes options
              here.
            </p>
          </div>
          <button
            type="button"
            onClick={onExport}
            disabled={selectedCount === 0}
            className="border border-accent bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent-deep disabled:cursor-not-allowed disabled:opacity-40 focus-visible:ring-2 focus-visible:ring-ink focus-visible:ring-offset-2"
          >
            Download packet PDF
            {selectedCount > 0 ? ` (${selectedCount})` : ""}
          </button>
        </div>

        <div className="space-y-6">
          {evaluation.requirements.map((item) => {
            const options = supportCandidatesFor(item);
            return (
              <div key={item.requirement_id} className="border-t border-line/70 pt-4">
                <div className="flex flex-wrap items-baseline justify-between gap-2">
                  <h3 className="font-display text-xl text-ink">{item.title}</h3>
                  <span
                    className={`border px-2 py-0.5 text-xs font-semibold uppercase tracking-[0.12em] ${statusStyles(item.status)}`}
                  >
                    {item.status.replaceAll("_", " ")}
                  </span>
                </div>

                {options.length === 0 ? (
                  <p className="mt-3 text-sm text-muted">
                    No supporting documents for this requirement yet.
                  </p>
                ) : (
                  <ul className="mt-3 space-y-2">
                    {options.map((candidate) => {
                      const doc = docById.get(candidate.document_id);
                      const label =
                        candidate.source_document_name ||
                        doc?.source_label ||
                        doc?.original_filename ||
                        candidate.document_id;
                      const docType =
                        candidate.source_document_type ||
                        doc?.document_type ||
                        "";
                      const pages = doc?.page_count;
                      const checked = selected.has(candidate.document_id);
                      return (
                        <li key={`${item.requirement_id}-${candidate.document_id}`}>
                          <label
                            className={`flex cursor-pointer items-start gap-3 border px-3 py-3 ${
                              checked
                                ? "border-[#1b7a6d]/40 bg-[#e7f6f2] text-[#0f5a51]"
                                : "border-line bg-white/50 text-ink-soft"
                            }`}
                          >
                            <input
                              type="checkbox"
                              className="mt-1"
                              checked={checked}
                              onChange={(event) =>
                                onToggleDocument(
                                  candidate.document_id,
                                  event.target.checked,
                                )
                              }
                            />
                            <span className="min-w-0 flex-1">
                              <button
                                type="button"
                                className="text-left font-medium hover:underline focus-visible:ring-2 focus-visible:ring-ink focus-visible:ring-offset-2"
                                onClick={(event) => {
                                  event.preventDefault();
                                  onOpenDocument(candidate.document_id);
                                }}
                              >
                                {label}
                              </button>
                              <div className="mt-1 text-xs uppercase tracking-[0.12em]">
                                {typeLabel(docType)}
                                {pages != null
                                  ? ` · ${pages} page${pages === 1 ? "" : "s"}`
                                  : ""}
                                {` · page ${candidate.source_page}`}
                              </div>
                            </span>
                          </label>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div>
        <h2 className="font-display text-2xl text-ink">Still needed</h2>
        {missing.length === 0 ? (
          <p className="mt-4 text-sm text-muted">
            Every requirement has at least one supporting document available.
          </p>
        ) : (
          <ul className="mt-4 space-y-3">
            {missing.map((item) => (
              <li
                key={item.requirement_id}
                className={`border px-3 py-3 ${statusStyles(item.status)}`}
              >
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <h3 className="font-medium">{item.title}</h3>
                  <span className="text-xs font-semibold uppercase tracking-[0.12em]">
                    {item.status.replaceAll("_", " ")}
                  </span>
                </div>
                {item.suggested_document_types.length > 0 && (
                  <p className="mt-2 text-xs uppercase tracking-[0.12em]">
                    Suggested: {item.suggested_document_types.join("; ")}
                  </p>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

/** Document IDs currently eligible for the packet (display_status = support). */
export function eligiblePacketDocumentIds(
  evaluation: PolicyEvaluation | null,
): string[] {
  if (!evaluation) return [];
  const ids = new Set<string>();
  for (const item of evaluation.requirements) {
    for (const candidate of supportCandidatesFor(item)) {
      ids.add(candidate.document_id);
    }
  }
  return [...ids];
}

