  setPatient(nextPatient);
  setDocuments(nextDocs);
  applyEvaluation(nextEvaluation);
  setPacket(nextPacket);
  const nextSelected =
    selectId === undefined
      ? (nextDocs[0]?.id ?? null)
      : selectId && nextDocs.some((d) => d.id === selectId)
        ? selectId
        : (nextDocs[0]?.id ?? null);
  setFailedDocId(null);
  setSelectedId(nextSelected);
}

